@'
import fs from 'node:fs';
let s=fs.readFileSync('src/core.js','utf8');s=s.replace('The prompt hook supplies task_id, actor and session_id. Refine that captured task with task_update instead of creating a duplicate; create separate tasks only for distinct requirements.','The prompt hook supplies task_id, actor and session_id. Refine that captured task with task_update instead of creating a duplicate; create separate tasks only for distinct requirements. For a reviewed follow-up to an existing requirement, use task_adopt with captured id, targetId, actor/session, summary and changed intent patch before development; it supersedes the captured duplicate and selects the target without claiming it.');s=s.replace('Fallback CLI: dip task create --title','Without global DIP, review .dip/intent-guide.md and .dip/tools/portable.mjs before explicitly invoking the Node 20+ portable intent helper. It persists intent only; automatic capture, leases and current verification require installed DIP.\\nFallback CLI: dip task create --title');fs.writeFileSync('src/core.js',s);
let a=fs.readFileSync('src/automation.js','utf8');a=a.replace('Refine this task with task_update instead of creating a duplicate. Classify informational','Refine this task with task_update instead of creating a duplicate. For a reviewed follow-up, use task_adopt to select an existing requirement before development; claim it separately. Classify informational');fs.writeFileSync('src/automation.js',a);
'@ | node --input-type=module
npx prettier --write src/core.js src/automation.js scripts/scale-benchmark.mjs
npm run check
npm test
